import React, { useState } from 'react';
import { View, Text, TouchableOpacity, Image, StyleSheet } from 'react-native';
import Modal from 'react-native-modal';

const HelpButton = ({ navigation }) => {
  const [visible, setVisible] = useState(false);

  return (
    <View style={styles.container}>
      <TouchableOpacity
        onPress={() => {
          setVisible(true);
        }}
      >
        <Image
          source={require('./assets/questionmark.png')}
          style={styles.icon}
        />
      </TouchableOpacity>

      <Modal
        style={styles.modal}
        onBackButtonPress={() => {
          setVisible(false);
        }}
        isVisible={visible}
      >
        <View style={styles.modalContent}>
          <TouchableOpacity
            style={styles.modalItem}
            onPress={() => {
              // Handle the action for the first item
              // Example: navigation.navigate('BookCourt');
              setVisible(false);
            }}
          >
            <Text style={styles.modalText}>How to book a court/Table?</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={styles.modalItem}
            onPress={() => {
              // Handle the action for the second item
              // Example: navigation.navigate('ComplainCourt');
              setVisible(false);
            }}
          >
            <Text style={styles.modalText}>How to complain about a court?</Text>
          </TouchableOpacity>
        </View>
      </Modal>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  icon: {
    height: 70,
    width: 70,
    marginLeft: 20,
    marginRight: 20,
  },
  modal: {
    width: '100%',
    margin: 0,
  },
  modalContent: {
    position: 'absolute',
    bottom: 0,
    height: 200,
    backgroundColor: '#fff',
    width: '90%',
  },
  modalItem: {
    width: '100%',
    height: 50,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
  },
  modalText: {
    fontSize: 18,
  },
});

export default HelpButton;
